  Skill_117318_AwakerSkillBackgroundStory = {
    Text = "অতীতে তার দুই চোখ ছিল অন্ধকারে ঢাকা, তাই সেই অন্ধকারকেই সে দিনের আলো মনে করত। \nএখন সে আবার পৃথিবীর প্রকৃত রূপ দেখতে পেয়েছে, তাই সে ঘুরে দাঁড়িয়ে বিপরীত পথে পা বাড়িয়েছে। \nযে কোনো সময়ই হোক, সে সর্বদা আলোর দিকেই এগিয়ে চলে।"
