  Skill_119763_AwakerSkillBackgroundStory = {
    Text = "সে অহংকারী। সে অহংকার দিয়ে তার হৃদয়ের অপূরণীয় শূন্যতা ঢেকে রাখে।\nসে ভুলে গেছে সে একসময় কে ছিল, ভুলে গেছে তার কে হওয়া উচিত ছিল।\nহাজার হাজার সমুদ্রপথের অনুসারী তার পদতলে নতজানু, আর সে সেই শ্রদ্ধার ধ্বনিতে ভুলে গেছে সবচেয়ে গুরুত্বপূর্ণ বিষয়টি——\nসে ইতিমধ্যেই এই বিবর্ণ নিয়তির কাছে আত্মসমর্পণ করেছে।"
  },
  Skill_119763_BattleDesc = {
    Text = "2টি অ্যারিথমেটিকা পাও এবং 2টি কার্ড ড্র করো। পরের টার্নের শুরুতে [Arg3] <SacrificeKeyWord:উৎসর্গ> ভোগ করো। <RippleKeywords:Aftershock>: [Arg4] <SacrificeKeyWord:উৎসর্গ> সরিয়ে দাও।"
  },
  Skill_119763_Desc = {
    Text = "2 অ্যারিথমেটিকা পাও এবং 2টি কার্ড ড্র করো। পরের টার্নের শুরুতে সর্বোচ্চ HP‑এর [Arg1]% সমান <SacrificeKeyWord:উৎসর্গ> ভোগ করো। <RippleKeywords:অনুকম্পন>: সর্বোচ্চ HP‑এর [Float:Arg2]% সমান \"উৎসর্গ\" স্তর সংখ্যা সরিয়ে ফেলো।"
  },
  Skill_119763_EffectNameList = {
    Text = "উৎসর্গ অপসারণ"
