  Skill_119763_Name = {
    Text = "অতলের স্তোত্র"
  },
  Skill_119764_AwakerSkillBackgroundStory = {
    Text = "মার্ফির হাতে থাকা হাতির দাঁতের মূর্তিটির উৎপত্তি নিয়ে নানা মুনির নানা মত।\nকেউ বলে মূর্তিটি মার্ফির নির্দেশনায় অনুসন্ধান করা গভীর সমুদ্রের ধ্বংসাবশেষ থেকে এসেছে, আবার কেউ বলে মূর্তিটি পবিত্র শিশুর সাথে তার বুকের স্পন্দিত হৃদয় থেকে জন্ম নিয়েছে।\nতবে এতে কোনো সন্দেহ নেই যে, অন্ধকার সমুদ্রের তলদেশে নীরবে দাঁড়িয়ে থাকা শঙ্খ-নিমজ্জিত নগরীর সাথে তার অগণিত সংযোগের প্রতীক এই মূর্তিটি, মার্ফি যেদিন 「প্রকৃত দেবমাতা」 হয়ে উঠেছিলেন সেদিনই সমুদ্রযাত্রীদের দৃষ্টিগোচর হয়েছিল।\nএরপর, বিশ্বাসীরা মার্ফিকে এই হাতির দাঁতের মূর্তি ব্যবহার করে ঝড়-ঢেউ ভেদ করতে এবং রক্তসমুদ্র বিদীর্ণ করতেও প্রত্যক্ষ করেছে।\nপরম ক্ষমতা কখনো নিছক অলীক প্রতীকে সীমাবদ্ধ থাকে না। মানুষের হাঁটু কেবল পরম শক্তির কর্তৃত্বের সামনেই নত হয়।"
  },
