  Skill_125371_AwakerSkillBackgroundStory = {
    Text = "তাঁরা কখনো তার উৎপত্তির কথা বলেন না, শুধু বলেন তার জন্মের সময় সেই অবর্ণনীয় বিপুল আনন্দের কথা।\nতোমার চেতনা উন্মত্ত আনন্দে গলে যাবে, তোমার অতীত উন্মত্ত আনন্দে গলে যাবে, তোমার করোটি উন্মত্ত আনন্দে গলে যাবে……তোমার মস্তিষ্ক উন্মত্ত আনন্দে গলে যাবে।\nএক টুকরো নরম কোমল মিষ্টান্ন——「বিরহ-ব্যাকুলতা」দিয়ে প্রস্তুত।"
