  Skill_130234_Name_1 = {
    Text = "অসম বিনিময়"
  },
  Skill_130234_UnknownName = {
    Text = "অসম বিনিময়"
  },
  Skill_130240_Desc = {
    Text = "একজন জাগরণকারীকে বেছে নিন যে [Arg1] পয়েন্ট অ্যালিমাস অর্জন করবে, অন্য জাগরণকারীরা [Arg2] পয়েন্ট অ্যালিমাস অর্জন করবে। যদি「মস」দলে থাকে, তাহলে তাৎক্ষণিকভাবে「ঘূর্ণি! প্রবাহ! গোলা!」মুক্তি দিয়ে পশ্চাদ্ধাবন করুন।"
  },
  Skill_130240_Name = {
    Text = "ডুবে যাওয়া নিষ্কলুষতা"
  },
  Skill_130351_Desc = {
    Text = "কার্ড ড্র পর্বের পর যদি হাতে থাকে, তাহলে「বাধ্যতামূলকভাবে খেলুন」১টি র‍্যান্ডম কমান্ড কার্ড এবং এটি ২ বার কার্যকর করুন।\nখেলার পর, পরবর্তী খেলা কমান্ড কার্ডটি অতিরিক্ত ২ বার কার্যকর হয়। [Arg1] বার খেলার পর ক্ষয় হয়（[Arg2]/[Arg1]）।"
  },
  Skill_130351_Name = {
    Text = "পুতুলনাচের পুতুল"
  },
  Skill_130385_Desc = {
    Text = "কার্ড ড্র পর্বের পরে যদি হাতে থাকে, তাহলে হাতের কার্ড থেকে এলোমেলো 2টি নির্দেশ কার্ড থেকে 1টি বাধ্যতামূলকভাবে খেলতে হবে এবং এটি 2 বার কার্যকর হবে।\nখেলার পরে, পরবর্তী নির্দেশ কার্ডের গণনা শক্তি খরচ 2 পয়েন্ট কমে যাবে এবং খেলা নির্দেশ কার্ড অতিরিক্ত 2 বার কার্যকর হবে। [Arg1] বার খেলার পরে ক্ষয় হবে ([Arg2]/[Arg1])।"
  },
  Skill_130385_Name = {
    Text = "পুতুলনাচের পুতুল"
