  Skill_132357_AwakerSkillBackgroundStory = {
    Text = "\"দেখো! অরিটা মাছের মতো বুদবুদ ওড়াচ্ছে!\""
  },
  Skill_132357_Desc = {
    Text = "<Block:[Block:Arg1]> পয়েন্ট শিল্ড অর্জন করুন এবং নিজে, খেলোয়াড় ও সামনের সারির শত্রুকে আলাদাভাবে অবস্থা যোগ করুন। খেলা মান ও প্রকৃত মান প্রতিটি 1 বার।"
