  Skill_132359_AwakerSkillBackgroundStory = {
    Text = "আলোর সাতটি রঙ, ঝলমলে ও মোহনীয়~"
  },
  Skill_132359_Desc = {
    Text = "খেলোয়াড় [Power:Arg1] পয়েন্ট <PowerIconKeywords:শক্তি>, <Block:[Block:Arg2]> পয়েন্ট শিল্ড, [Heal:Arg3] পয়েন্ট নিরাময়, [TentaclePower:Arg4] পয়েন্ট <TentacleInjurieIconKeywords:শুঁড় ক্ষতি>, [Counterattack:Arg5] স্তর <RetaliateIconKeywords:পাল্টা আক্রমণ> অর্জন করে, সামনের সারির শত্রুদের <Damage:[Damage:Arg6]> পয়েন্ট ক্ষতি [Arg7] বার প্রদান করে, [Poison:Arg8] স্তর <IntoxicationIconKeywords:বিষক্রিয়া> প্রয়োগ করে, [Exhaustion:Arg9] স্তর <ExhaustionIconKeywords:ক্লান্তি> প্রয়োগ করে, [FateCut:Arg10] স্তর <CutKeywords:ভাগ্যের রায়> প্রয়োগ করে।"
  },
  Skill_132359_Name = {
    Text = "রঙিন আল্টিমেট"
  },
  Skill_132359_OverLimitUtlSkillDesc = {
    Text = "<Damage:[Damage:Arg1]> <PunctureDamagewords:ভেদকারী ক্ষতি> প্রদান করুন। ড্র পাইল এবং বাতিল তাসের স্তূপ থেকে সর্বোচ্চ 10টি 「গ্রন্থি বিভাজন」 কার্ড ভোগ করুন, প্রতিটি অতিরিক্ত 1 বার করে ক্ষতির উদাহরণ যোগ করবে। আপনার হাতে 2টি 「গ্রন্থি বিভাজন」 কার্ড নিন। এই যুদ্ধে অরিটার পরবর্তী ক্ষতি [Arg2] পয়েন্ট বৃদ্ধি পাবে। [Power:Arg2] <PowerIconKeywords:STR> এবং [TentaclePower:Arg2] <TentacleInjurieIconKeywords:শুঁড় ক্ষতি> অর্জন করুন, এবং পরবর্তী 5 বার আপনি 「গ্রন্থি বিভাজন」 খেললে, প্রতি বার 1টি করে কার্ড ড্র করুন।"
  },
