  Skill_132428_Name = {
    Text = "পরীক্ষা·জাগরণ"
  },
  Skill_132429_AwakerSkillBackgroundStory = {
    Text = "\nসমুদ্র গভীর ও নীরব, বয়ে বেড়ায় জীবনের কামনা আর মৃত্যুভয়ের ভার।\nতবু কেউ কেউ আছে, যারা হাসি আর দুষ্টুমিতে সেই সমুদ্র ভরিয়ে তুলতে চায়—যখন অরিটা এমন আমন্ত্রণ বাড়িয়ে দেয়, তখনই মনে হয়, “ওর সঙ্গে একটু মজা করলেই বা ক্ষতি কী,” আর সহজ সরল আনন্দে হৃদয় ভরে ওঠে।"
  },
  Skill_132429_Desc_0 = {
    Text = "<Damage:[Damage:Arg1]> ক্ষতি করো। ড্র পাইল ও বাতিল তাসের স্তূপ থেকে সর্বোচ্চ ১০টি \"গ্রন্থি বিভাজন\" ব্যয় করো, প্রতিটি অতিরিক্ত ১টি করে ক্ষতির আঘাত যোগ করে। হাতে ২টি \"গ্রন্থি বিভাজন\" নাও। এই যুদ্ধে অরিটার ক্ষতি আউটপুট [Arg2] দ্বারা বৃদ্ধি পায়।"
  },
  Skill_132429_Desc_2 = {
    Text = "<Damage:[Damage:Arg1]> <PunctureDamagewords:ভেদন ক্ষতি> দাও। ড্র পাইল এবং বাতিল তাসের স্তূপ থেকে সর্বোচ্চ 10টি 「গ্রন্থি বিভাজন「 কার্ড ভোগ করো, প্রতিটি অতিরিক্ত একবার করে ক্ষতি ঘটায়। হাতে 2টি 「গ্রন্থি বিভাজন「 কার্ড রাখো। এই যুদ্ধে অরিটা যে ক্ষতি করে, তা [Arg2] পয়েন্ট বৃদ্ধি করো।"
  },
