  Skill_132432_AwakerSkillBackgroundStory = {
    Text = "বালকেরা ধীরে ধীরে রূপকথার আসল রূপ চিনে ফেলে, আর মিথের আড়ালে লুকোনো উপকথা বুঝতে শেখে। মানুষের ভাষায়, এই প্রক্রিয়াকেই বলে “বড় হয়ে ওঠা”।\nকিন্তু কিছু বালক ক্রমশ আরও বেশি করে শোবার সময়ের গল্পেই বিশ্বাস স্থাপন করে; তারা একগুঁয়ে ভেবে বসে, আকাশে সত্যিই নাকি রঙধনু সেতু আছে, আর গভীর সাগরের তলায় ডুবে আছে হারানো সভ্যতা।\nঅরিটা এইসব গল্প ভালোবাসে, আর এই আনন্দ আরও অনেক বন্ধুর সঙ্গে ভাগ করে নিতে চায়।"
  },
  Skill_132432_Desc_0 = {
