  Skill_144491_AwakerSkillBackgroundStory = {
    Text = "লোভ হলো মানব স্বভাবের আসল রং।\nমিষ্টির প্রলোভন কেউ প্রত্যাখ্যান করতে পারে না, এমনকি পরী গডমাদার নিজেও নয়।\nকারাবু মুখ ফাঁক করে হাসল, কালো কালো ধারালো দাঁত বেরিয়ে পড়ল।"
  },
  Skill_144491_BattleDesc_0 = {
