  Skill_146013_AwakerSkillBackgroundStory = {
    Text = "খুব কম, খুব কম সময়ই লোটান তার তলোয়ার ফিরিয়ে নেয়।\nসেই ভিন্নবর্ণের দুই চোখ শান্তভাবে পর্যবেক্ষণ করছে। তলোয়ার গুটিয়ে নেওয়া, সবসময় শুধুমাত্র আরও ভালোভাবে আঘাত করার জন্য।"
