  Skill_146016_AwakerSkillBackgroundStory = {
    Text = "দেবতা তার আত্মা ও দেহ ছিন্ন করেছিল、মনে করেছিল এটাই কেওসের বিরুদ্ধে চূড়ান্ত বিচার।\nকিন্তু শূন্য আত্মা কখনো অনুসন্ধান থামায়নি、বিচ্ছিন্ন শক্তিও কখনো সত্যিকার অর্থে বিলীন হয়নি।\nযখন অস্থি-বর্ম আবার তার দেহ ঢেকে নিল、যখন লেভিয়াথানের স্পন্দন আবার তার ইচ্ছার সাথে অনুরণিত হলো——সমস্ত বন্ধন সেই মুহূর্তে চূর্ণ হয়ে গেল।\nআত্মা ও দেহ নক্ষত্র-সমুদ্রের গভীরে আবার একত্রিত হলো। কেওসের পশু আর অসম্পূর্ণ নয়।\nএই নক্ষত্র-সমুদ্র আবার সম্পূর্ণ তাকে স্বাগত জানাবে।"
  },
  Skill_146016_BattleDesc_0 = {
