  Skill_146017_AwakerSkillBackgroundStory = {
    Text = "লেভিয়াথানের সবচেয়ে তীক্ষ্ণ দাঁতটি ঘষে ছোট ফলায় পরিণত করা হয়েছে, সে এটিকে বলে 「噬」।\nদুর্বলদের প্রতি এর কোনো আগ্রহ নেই, তরবারির ফলা সবসময় সবচেয়ে শক্তিশালী শত্রুর দিকে মুখ করা থাকে। ব্লেড অত্যন্ত দ্রুতগতিতে ছুটে যায়, যখন অবশিষ্ট ছায়া মিলিয়ে যায়, তখন তারার সমুদ্রের মতো বিশাল শক্তিও গ্রাস হয়ে যায়।\nএর লোভের কোনো শেষ নেই, সেই ক্ষুধার্ত দৃষ্টি জন্মের মুহূর্ত থেকেই লোটানকে অনুসরণ করে, প্রতিবার আঘাত করার সময় লোটানের শরীর থেকে এক টুকরো কারো কামড়ে নেয়।\nলোটান কখনো পরোয়া করে না। সে রক্ত দিয়ে এটিকে পোষে, শক্তি দিয়ে এটিকে দমন করে। সে এটিকে সবচেয়ে শক্তিশালী প্রতিদ্বন্দ্বীর দিকে ছুড়ে দেয়, শক্তির স্বাদ, সে এটির সাথে একসাথে উপভোগ করে।"
  },
  Skill_146017_BattleDesc = {
