  Skill_21615_AwakerSkillBackgroundStory = {
    Text = "ক্ষয় প্রপঞ্চের কারণে ওগিয়ারের স্মৃতি ছিন্নভিন্ন হয়ে গেছে।\nসে নৃত্যসভার হাসি মনে করতে পারে, কিন্তু সেই সভার মূল ব্যক্তির নাম ভুলে গেছে; সে মনে করতে পারে নাইট অর্ডারে প্রশিক্ষণ নিয়েছিল, কিন্তু জানে না কেন গ্র্যান্ড ডিউক তাকে এত অল্প বয়সে নাইট করেছিলেন; সে মনে করতে পারে অশ্বারোহী বাহিনীর নিচে চাপা পড়ে মৃত্যু হয়েছিল, কিন্তু মনে করতে পারে না সে যে হাসি রক্ষা করেছিল তা কেমন ছিল।\nকেউ তাকে দোষ দিতে পারে না, সে একজন নাইটের সমস্ত কর্তব্য পালন করেছে——যার মধ্যে রক্ষার সংকল্পের জন্য নিজের জীবন উৎসর্গ করাও অন্তর্ভুক্ত।"
  },
  Skill_21615_Desc_0 = {
