  Skill_23761_Desc = {
    Text = "কাসিয়া 「ছায়া স্থানান্তর」 অর্জন করে। প্রতিপক্ষ 10টি কার্ড খেললে, তার সামনে সঙ্গে সঙ্গে কম HP‑যুক্ত একটি 「ক্লোন」 আহ্বান করো।"
  },
  Skill_23761_Name = {
    Text = "জাগরণ"
  },
  Skill_23810_Desc = {
