  Skill_3973_AwakerSkillBackgroundStory = {
    Text = "নীরবতায় গ্রাস হওয়ার মুহূর্তে, সে যেন দেখতে পেল ডুবে মরা সেই পরিচারিকাকে।\nপরিচারিকার ত্বক ফ্যাকাশে সাদা, যেন একটি পচা শাপলা হ্রদের বুকে শুয়ে আছে, তার গলার ক্ষতচিহ্ন নীলচে-সাদা শিরা বরাবর ছড়িয়ে যাচ্ছে দৃষ্টির অগোচরে কোনো সুদূরে।\n'তোমার ক্যাটস আই ওপাল গলার হারটা দেখো,' মৃতদেহ বলল, 'সব ছাই হয়ে গেছে। ছাই হয়ে গেছে......'"
  },
  Skill_3973_Desc = {
    Text = "<Heal:[Heal:Arg1]> HP পুনরুদ্ধার করো এবং <Block:[Block:Arg2]> চরিত্রের ঢাল লাভ করো। টার্নের শেষে হাতে থাকলে, অ্যারিথমেটিকা ব্যয় 1 বাড়ে, এবং HP পুনরুদ্ধার ও চরিত্রের ঢাল উভয়ই দ্বিগুণ হয়। সর্বোচ্চ [Arg3] বার পর্যন্ত স্তর সংখ্যা জমা হতে পারে।"
