  Skill_3975_Desc = {
    Text = "<Damage:[Damage:Arg1]> ক্ষতি [AttackTimes:Arg2] বার করো। [Arg3] টার্নের জন্য <FragileIconKeywords:ভঙ্গুর> প্রয়োগ করো।"
  },
  Skill_3977_AwakerSkillBackgroundStory = {
    Text = "「কাছে এসো, লজ্জা পেও না, টুপি মহাশয়কে তোমার হাসি আর আনন্দের স্বাদ নিতে দাও।」\nমাস্টার ক্যাসিয়া টুপির কিনারায় হাত দিলেন, আর ধুম করে এক গোছা ফিতা আর কার্ড বের করলেন।\n「মনে মনে তোমার কার্ড বেছে নাও। চুপ! কাউকে বলো না। মাস্টার ক্যাসিয়া তোমাকে বলে দেবেন কোনটা তোমার একমাত্র কার্ড।」"
  },
  Skill_3977_Desc_0 = {
    Text = "「Strike」 হিসেবে গণ্য। <DimensionalSpaceIconKeywords:Ultra Space> থেকে যেকোনো 1টি কার্ড বেছে নিয়ে হাতে নাও, তার অ্যারিথমেটিকা ব্যয় 2 কমাও। এলোমেলোভাবে <Damage:[Damage:Arg1]> ক্ষতি [Arg2] বার দাও, এবং [Power:Arg3] অস্থায়ী <PowerIconKeywords:Strength> পাও।"
  },
  Skill_3977_Desc_3 = {
    Text = "「স্ট্রাইক「 হিসেবে গণ্য। <DimensionalSpaceIconKeywords:আল্ট্রা স্পেস> থেকে যেকোনো 1টি কার্ড বেছে নিয়ে হাতে নাও, এবং তার অ্যারিথমেটিকা ব্যয় 2 কমাও। এলোমেলোভাবে <Damage:[Damage:Arg1]> ক্ষতি [Arg2] বার করো, এবং [Power:Arg3] অস্থায়ী <PowerIconKeywords:Strength> অর্জন করো। <RippleKeywords:অনুকম্পন>: ড্র পাইলের মধ্যে 1টি <DerivativeCardKeywords_4:\"অন্তর্দৃষ্টি\"> শাফল করো।"
