  Skill_3979_AwakerSkillBackgroundStory = {
    Text = "Schizophrenia.\nএই শব্দটি আবিষ্কার হওয়ারও অনেক আগে, হার্বার্ট তার গবেষণাগারে ইতিমধ্যে অসংখ্য কেস তৈরি করে ফেলেছিলেন।\n24 নিঃসন্দেহে তার মধ্যে সর্বশ্রেষ্ঠ সৃষ্টি, তার ব্যক্তিত্ব বিস্ময়কর গতিতে ক্রমাগত বৃদ্ধি পাচ্ছিল, এবং একে অপরকে কোনোভাবেই প্রভাবিত করত না।\nএক অর্থে, তার মস্তিষ্ক ছিল একটি জনাকীর্ণ অ্যাপার্টমেন্টের মতো, কোলাহলপূর্ণ ভাড়াটেদের দিয়ে ঠাসা।"
  },
  Skill_3979_Desc_0 = {
