  Skill_3980_Desc = {
    Text = "<Damage:[Damage:Arg1]> ক্ষতি [AttackTimes:Arg2] বার দাও এবং <Block:[Block:Arg3]> চরিত্রের ঢাল পাও।"
  },
  Skill_3981_AwakerSkillBackgroundStory = {
    Text = "অন্য জাতি থেকে উত্তরাধিকারসূত্রে প্রাপ্ত, ধর্মবিরোধী বলে বিবেচিত রক্তধারা।\nকেবল এর মহিমায় অটল বিশ্বাস, এর শ্রেষ্ঠত্বে অবিচল আস্থাই এই নিষ্ঠুর পৃথিবীতে বেঁচে থাকার একমাত্র উপায়।\nঅর্ন চাচার রেখে যাওয়া সেই হস্তলিখিত পুঁথি, আর তাতে চিত্রিত গভীর সমুদ্রের সেই মনোমুগ্ধকর প্রাচীন নগরী—এটাই তার একমাত্র আত্মিক আশ্রয়।\n「রক্তধারা জাগ্রত হওয়ার মুহূর্তে, নিশ্চয়ই গভীর সমুদ্রের পরম শক্তি লাভ করা যাবে।」"
  },
  Skill_3981_Desc = {
    Text = "<Heal:[Heal:Arg3]> পয়েন্ট HP পুনরুদ্ধার করে এবং নিজের <WeaknessIconKeywords:দুর্বলতা> অবস্থা দূর করে, সকল শত্রুর উপর [Arg4] স্তর <VulnerabilityIconKeywords:ক্ষত সংবেদনশীলতা> প্রয়োগ করে। <TentacleInjurieIconKeywords:শুঁড়ের ক্ষতি> +[TentaclePower:Arg1]। <RetaliateIconKeywords:পাল্টা আক্রমণ> +[Counterattack:Arg2]। পরবর্তী টার্ন শুরু হওয়ার আগে, প্রতিবার আক্রমণ খাওয়ার পর, 1টি শুঁড় আক্রমণকারীকে পাল্টা আক্রমণ করবে।"
