  Skill_3994_AwakerSkillBackgroundStory = {
    Text = "কোনো বীজই অঙ্কুরোদগমের জন্য তৃষ্ণার্ত নয় এমন হয় না।\nউদ্ভিদ সূর্যালোক ও বৃষ্টির শিশিরে স্নান করে মাটি ভেদ করে ওঠে, শিশু ভালোবাসা ও আশায় সিক্ত হয়ে বেড়ে ওঠে।\nফিন্ট দোলনায় কুণ্ডলী পাকিয়ে শুয়ে, মূল্যবান পুষ্টি বুকে আঁকড়ে ধরে, নীরবে সেই মুহূর্তটির আগমনের অপেক্ষায় রয়েছে……"
