  Skill_4019_AwakerSkillBackgroundStory = {
    Text = "“এক থেকে সব, সব আবার একে ফিরে যায়” — এই তত্ত্বের মতোই, সে একসময় প্যারাডক্সের ফাঁদে পতিত হয়েছিল।"
  },
  Skill_4019_Desc_0 = {
    Text = "<Posse:[Arg1]> কীফ্লেয়ার অর্জন করো। আগের টার্নে খেলা শেষ 3টি ভিন্ন অ-উদ্ভূত কমান্ড কার্ডের অস্থায়ী কপি -1 অ্যারিথমেটিকা ব্যয়, <DepleteIconKeywords:ক্ষয়>, <NothingnessIconKeywords:Fleeting> সহ তোমার হাতে নাও। যদি হাতে নেয়ার মতো যথেষ্ট কমান্ড কার্ড না থাকে, তবে অনুপস্থিত প্রতিটি কমান্ড কার্ডের জন্য একটি করে কার্ড ড্র করো।"
  },
  Skill_4019_Desc_3 = {
    Text = "<Posse:[Arg1]> কীফ্লেয়ার অর্জন করো। আগের টার্নে খেলা শেষ 3টি ভিন্ন অ-উদ্ভূত কমান্ড কার্ডের অস্থায়ী কপি -1 অ্যারিথমেটিকা ব্যয়, <DepleteIconKeywords:ক্ষয়>, <NothingnessIconKeywords:Fleeting> সহ তোমার হাতে নাও। যদি হাতে নেয়ার মতো যথেষ্ট কমান্ড কার্ড না থাকে, তবে অনুপস্থিত প্রতিটি কমান্ড কার্ডের জন্য একটি করে কার্ড ড্র করো। তোমার বর্তমান পসের বদলে 1টি লক করা নয় এমন পসে বেছে নাও। কোনো পসে ব্যবহার করার পর বা যুদ্ধের শেষে তোমার বর্তমান পসে পুনরুদ্ধার হবে।"
