  Skill_4019_OverLimitUtlSkillDesc_0 = {
    Text = "<Posse:[Arg1]> পয়েন্ট S-শক্তি অর্জন করুন। গত রাউন্ডে সর্বশেষ খেলা 3টি ভিন্ন অ-উদ্ভূত কমান্ড কার্ডের আদি প্রতিলিপি হাতে রাখুন, সেগুলির অ্যারিথমেটিকা ব্যয় 0 করুন এবং <DepleteIconKeywords:ব্যয়> ও <NothingnessIconKeywords:মায়া> অর্জন করুন। যদি হাতে রাখার মতো যথেষ্ট কমান্ড কার্ড না থাকে, তাহলে সমপরিমাণ কার্ড ড্র করুন। সীমা উপেক্ষা করে 3 স্তর <TimeBeacon2:নেগেনট্রপি> অর্জন করুন।"
  },
  Skill_4019_OverLimitUtlSkillDesc_3 = {
    Text = "<Posse:[Arg1]> Keyflare অর্জন করো। আগের টার্নে ব্যবহৃত শেষ 3টি ভিন্ন অ-উদ্ভূত কমান্ড কার্ডের অনুলিপি হাতে নাও; তাদের অ্যারিথমেটিকা ব্যয় 0 করো এবং তাদের <DepleteIconKeywords:ক্ষয়>, <NothingnessIconKeywords:Fleeting> দাও। হাতে রাখার মতো যথেষ্ট কমান্ড কার্ড না থাকলে, অনুপস্থিত প্রতিটি কমান্ড কার্ডের জন্য 1টি করে কার্ড ড্র করো। 1টি আনলক করা Posse বেছে নিয়ে বর্তমান Posse‑এর জায়গায় স্থাপন করো। বর্তমান Posse, Posse ব্যবহার করার পর বা যুদ্ধের শেষে পুনরুদ্ধার হবে। সীমা উপেক্ষা করে <TimeBeacon2:Negentropy>‑র 3টি স্ট্যাক অর্জন করো।"
  },
