  Skill_4023_AwakerSkillBackgroundStory = {
    Text = "লিজ এখনও সেই দিনের দৃশ্য মনে করতে পারে যেদিন সে সবুজ শিখা লাভ করেছিল।\nসবুজাভ অগ্নিবীজ তার হাতের তালুতে উঠে নাচছিল, তাকে সেই দীর্ঘদিন ধরে চেপে রাখা ইচ্ছা পূরণ করতে তাগিদ দিচ্ছিল।"
  },
  Skill_4023_Desc = {
    Text = "<Damage:[Damage:Arg1]> <PunctureDamagewords:ভেদন ক্ষতি> করো, এবং ক্ষতির [Arg2]% পরিমাণ <IntoxicationIconKeywords:বিষক্রিয়া> হিসেবে প্রয়োগ করো। টার্নের শেষে, যদি হাতে বা <DimensionalSpaceIconKeywords:আল্ট্রা স্পেস>-এ থাকে, তবে 「<DerivativeCardKeywords_19:কলুষিত সবুজ শিখা>」-তে উন্নয়ন অর্জন করো। পর্যাপ্ত অ্যারিথমেটিকা না থাকলেও এটি ব্যবহার করা যাবে; সে ক্ষেত্রে এর প্রভাব বদলে <Energy:[Energy:Arg3]> অ্যালিমাস অর্জন করবে এবং ক্ষয় হবে।"
