  Skill_4027_AwakerSkillBackgroundStory = {
    Text = "\nFaint পাতলা খোলসটি ছেড়ে যেতে পারত না, তাই Tinct প্রায়ই তার সঙ্গ দিত, তার জন্য এই রেকুইয়েম গেয়ে।\n\"আমি তোমার জীবনশক্তি শোষণ করতে যাচ্ছি।\" Faint বলল।\n\"তাতে কিছু যায় আসে না, আমাদের জীবন তো এক।\" জবাব দিল Tinct।"
