  Skill_4136_Name = {
    Text = "বিকৃত হৃদয়"
  },
  Skill_4137_AwakerSkillBackgroundStory = {
    Text = "নিষ্কর্ষ হলো যুক্তিতর্কের এক রূপ; সঠিক পূর্বধারণা আয়ত্ত করতে পারলেই কেবল নির্ভুল উপসংহারে পৌঁছানো যায়।\nঅনুসন্ধান কর্মকর্তা হওয়ার আগে থেকেই রামোনা নিষ্কর্ষের মাধ্যমে পৃথিবীকে বোঝার চেষ্টা করছিল।\nযথেষ্ট সব অভিযান পেরিয়ে গেলে, হয়তো সে একদিন ভাবতে শুরু করবে—উদ্বৃত্তি ব্যবহার করেও কি বোঝা যায় না অনেক কিছু।"
  },
  Skill_4137_Desc_0 = {
    Text = "<Posse:[Arg1]> কীফ্লেয়ার অর্জন করো। ড্র পাইল বা বাতিল তাসের স্তূপ থেকে 1টি কার্ড বেছে নিয়ে হাতে নাও, এবং তার অ্যারিথমেটিকা ব্যয় 0 তে নামিয়ে আনো।"
  },
  Skill_4137_Desc_3 = {
    Text = "<Posse:[Arg1]> কীফ্লেয়ার অর্জন করো। ড্র পাইল বা বাতিল তাসের স্তূপ থেকে 1টি কার্ড বেছে নিয়ে হাতে নাও, এবং তার অ্যারিথমেটিকা ব্যয় 0 করো। ড্র পাইলে 1টি <DerivativeCardKeywords_4:\"অন্তর্দৃষ্টি\"> শাফল করো।"
  },
  Skill_4137_EffectNameList = {
    Text = "সিলভার কী চার্জ"
  },
  Skill_4137_Name = {
    Text = "মুন্ডুস ডিক্রি"
  },
  Skill_4137_OverLimitUtlSkillDesc_0 = {
    Text = "<Posse:[Arg1]> পয়েন্ট S-শক্তি অর্জন করুন। ড্র পাইল বা বাতিল তাসের স্তূপ থেকে 1টি কার্ড বেছে হাতের কার্ডে রাখুন এবং এর অ্যারিথমেটিকা ব্যয় 0 পয়েন্টে পরিণত করুন। সমস্ত শত্রুকে 1 রাউন্ডের জন্য <WeaknessIconKeywords:দুর্বলতা> এবং <VulnerabilityIconKeywords:দুর্বল> করুন, পরবর্তী মুক্তি পাওয়া পসি 2 বার কার্যকর হবে।"
  },
  Skill_4137_OverLimitUtlSkillDesc_3 = {
    Text = "<Posse:[Arg1]> কীফ্লেয়ার অর্জন করো। ড্র পাইল বা বাতিল তাসের স্তূপ থেকে 1টি কার্ড বেছে নিয়ে হাতে নাও, এবং তার অ্যারিথমেটিকা ব্যয় 0-তে নামিয়ে আনো। ড্র পাইলে 1টি <DerivativeCardKeywords_4:\"Insight\"> শাফল করো। সব শত্রুর ওপর 1 টার্নের জন্য <WeaknessIconKeywords:Weakness> এবং <VulnerabilityIconKeywords:Vulnerable> প্রয়োগ করো। তুমি যে পরের পসি মুক্ত করবে, তা দ্বিগুণ কার্যকর হবে।"
  },
  Skill_4138_AwakerSkillBackgroundStory = {
    Text = "দশ বছর বয়সে রামোনা যুদ্ধ প্রশিক্ষণ নেওয়ার ইচ্ছা প্রকাশ করেছিল।\nওটা কোনো নাইটদের খেলা খেলার খেয়াল ছিল না; পালক পিতার অপচয় আর আড়ম্বর নিজের চোখে দেখে মেয়েটি সিদ্ধান্ত নিয়েছিল, সামনে আসতে পারে এমন দেউলিয়ার জন্য আগে থেকেই প্রস্তুতি নেবে।\n\"রানির প্রহরী হলে নিশ্চয়ই থানার চাকরির চেয়ে বেশি বেতন পাওয়া যায়, তাই না?\""
  },
  Skill_4138_Desc_0 = {
    Text = "<Damage:[Damage:Arg1]> ক্ষতি [Arg2] বার করো। ব্যবহার শেষে, 「রানির তরবারি」-র ক্ষতির সংখ্যা 1 করে বাড়াও, সর্বোচ্চ [Arg3] বার পর্যন্ত। [Arg7] অস্থায়ী রিয়েলম দক্ষতা অর্জন করো।"
  },
  Skill_4138_Desc_1 = {
    Text = "<Damage:[Damage:Arg1]> পয়েন্ট ক্ষতি [Arg5] বার করে, প্রতিবার ক্ষতি করলে [Power:Arg4] পয়েন্ট অস্থায়ী <PowerIconKeywords:শক্তি> অর্জন করে। খেলার পরে「রানির তরবারি」এর ক্ষতির সংখ্যা +1 বৃদ্ধি পায়, সর্বোচ্চ [Arg6] বার পর্যন্ত বাড়ানো যায়। [Arg7] পয়েন্ট অস্থায়ী ক্ষেত্র দক্ষতা অর্জন করে। <RippleKeywords:অবশিষ্ট তরঙ্গ>：রামোনার রৌপ্য চাবি রিচার্জের সমতুল্য 300% S-শক্তি অর্জন করে।"
  },
  Skill_4138_Desc_3 = {
    Text = "<Damage:[Damage:Arg1]> পয়েন্ট ক্ষতি [Arg5] বার করে, প্রতিবার ক্ষতি করলে [Power:Arg4] পয়েন্ট অস্থায়ী <PowerIconKeywords:শক্তি> অর্জন করে। খেলার পরে「রানির তরবারি」এর ক্ষতির সংখ্যা +1 বৃদ্ধি পায়, সর্বোচ্চ [Arg6] বার পর্যন্ত বাড়ানো যায়। [Arg7] পয়েন্ট অস্থায়ী ক্ষেত্র দক্ষতা অর্জন করে। <RippleKeywords:অবশিষ্ট তরঙ্গ>：রামোনার রৌপ্য চাবি রিচার্জের সমতুল্য 300% S-শক্তি অর্জন করে।"
