  Skill_4152_AwakerSkillBackgroundStory = {
    Text = "রক্তে ভেসে যাক মাটি, লাশে ছেয়ে যাক প্রান্তর, হৃদয় বিদীর্ণ করা যন্ত্রণাই সইতে হোক।\nঈশ্বরের রাজ্য পুনরায় পৃথিবীতে প্রতিষ্ঠিত করতে, এসব নগণ্য ত্যাগ মাত্র।\nসে কেবল আক্ষেপ করে যে সে সেই নির্বাচিত ব্যক্তি নয়, সেই খাঁচায় বন্দি কন্যাটি নয়।"
  },
  Skill_4152_Desc_0 = {
