  Skill_4154_AwakerSkillBackgroundStory = {
    Text = "শোনো, এটি নিজের জন্য বাজানো মৃত্যুঘণ্টার ধ্বনি।\nসে উন্মাদ অন্বেষণকারী নয়, দিশেহারা পথভ্রষ্টও নয়, সে কেবল নীরবে নিজের শেষ পথ বেছে নিয়েছে।\nঝরে পড়া পাপড়িগুলো তার আচারের জন্য নৃত্য করে, উন্মত্ত সমুদ্রবায়ু তার শোকগাথায় বিলাপ করে।\nসেই হৃদয় কাঁপানো ঘণ্টাধ্বনির পর, পৃথিবী ক্ষণিকের জন্য মৃত্যুর মতো নীরবতায় ডুবে যায়।"
