  Skill_4233_AwakerSkillBackgroundStory = {
    Text = "কোমল সমুদ্রের জল ঝরে পড়া পাপড়িগুলোকে বয়ে নিয়ে যায়, প্রস্ফুটিত তরঙ্গ যেন শাপলার মতো খুলে আর বন্ধ হয়।\nযদি তুমি অসতর্ক হও, তবে সেই শান্ত বাহ্যিক রূপে প্রতারিত হবে। নিস্তব্ধ চাঁদের আলোয় মৃদু জোয়ারের শব্দ, আসলে সবকিছু গ্রাস করার শক্তি লুকিয়ে রাখে।\nঠিক তার ভালোবাসা ও ঘৃণার মতো, কখনো মুখে প্রকাশ পায়নি, কিন্তু উত্তাল ঢেউয়ের মাঝে তীব্রভাবে প্রতিধ্বনিত হয়।"
