  Skill_4278_AwakerSkillBackgroundStory = {
    Text = "উষ্ণ রক্ত তার গাল বেয়ে গড়িয়ে পড়ল, সে মুখ হাঁ করে এক সারি ধারালো ছুরির মতো দাঁত বের করল।\nদুর্বলের উপর সবলের আধিপত্য—এটাই জগতের মূল নিয়ম, আর সে হবে চিরকালের শিকারি।\nসে লাশের স্তূপের উপর দিয়ে হেঁটে গেল, বিজয়ের গর্জন ছড়িয়ে দিল চারদিকে।"
