  Skill_4284_AwakerSkillBackgroundStory = {
    Text = "সে সবসময় নতুন সৈনিকদের বলে: যতই ক্লান্ত হও, যতই দুর্বল হও, কখনো অস্ত্র নামিও না। এটিকে তোমার সবচেয়ে ঘনিষ্ঠ সঙ্গী, সবচেয়ে মজবুত ঢাল বানাও।\nযুদ্ধক্ষেত্রে, কেবল যথেষ্ট সতর্করাই বেঁচে থাকতে পারে।"
