  Skill_4284_BattleDesc_0 = {
    Text = "<Block:[Block:Arg1]> চরিত্রের ঢাল [Arg2] বার অর্জন করে। টার্নের শেষে, যদি হাতে থাকে (In Hand), তবে পরেরবার ব্যবহার করলে অতিরিক্ত 1 বার চরিত্রের ঢাল সৃষ্টি করবে। সব জাগরণকারীর থেকে <CardKeyWord:সিলমোহর> অপসারণ করুন।"
