  Skill_4289_Desc = {
    Text = "<Damage:[Damage:Arg1]> ক্ষতি করো, [AttackTimes:Arg2] বার এবং [Arg3] চরিত্রের ঢাল পাও। তোমার টার্নের শেষে, হাতে থাকা প্রতিটি কার্ডের জন্য অতিরিক্ত [Arg4] চরিত্রের ঢাল পাও।"
