  Skill_4313_Name = {Text = "বিষ"},
  Skill_4314_AwakerSkillBackgroundStory = {
    Text = "তাঁদের জন্য তার রক্ত উত্তপ্ত, তাঁদের জন্য তার মস্তিষ্ক উদ্বেলিত।\nএই অপার্থিব সন্তানেরা তার চিরকালের মনোবাসনা পূরণ করতে পারুক বা না পারুক, তাঁরা শূন্যতার মাঝে টিকে থাকুক বা না থাকুক।\nতাইসি প্রতিটি পবিত্র সন্তানের জন্মকে গভীর ভালোবাসায় স্বাগত জানান।"
