  Skill_4339_AwakerSkillBackgroundStory = {
    Text = "একবার কেউ রসিকতা করে আইজিসকে জিজ্ঞেস করেছিল যে সে নিজের জন্য একটা মাফলার বুনতে পারবে কি না, কারণ তার কাছে সুই থেকে শুরু করে সুতো পর্যন্ত সবকিছুই আছে।\nআইজিস লজ্জায় মাথা নিচু করল। সে কাউকে বলেনি যে তার মাথার সুইগুলো কোনো সাজসজ্জা নয়, বরং তার চোখের শক্তিকে দমন করার বিশেষ যন্ত্র।\nকয়েকদিন পর, সে ধার করা সুই দিয়ে একটি রঙিন মাফলার তৈরি করল।"
  },
  Skill_4339_Desc_0 = {
    Text = "এজিস <Energy:[Energy:Arg1]> অ্যালিমাস পায়। <ExaltIconKeywords:Rouse>: এজিস কার্ড খেলার পর, সব শত্রুর ওপর [Arg2] টার্নের জন্য <VulnerabilityIconKeywords:দুর্বল> প্রয়োগ করো।"
  },
  Skill_4339_Desc_15 = {
    Text = "এগিস <Energy:[Energy:Arg1]> পয়েন্ট উন্মত্ত শক্তি অর্জন করে। <ExaltIconKeywords:আধ্যাত্মিক জাগরণ>：এগিস কার্ড খেলার পর、সকল শত্রুর উপর [Arg2] রাউন্ডের <VulnerabilityIconKeywords:দুর্বলতা> প্রয়োগ করে। এগিস উন্মত্ত বিস্ফোরণ ব্যবহারের পর নিজের পরবর্তী「প্রতিরক্ষা」কার্ড 3 বার কার্যকর হয়、অতিরিক্তভাবে উন্মত্ত বিস্ফোরণের মূল ক্ষতি 50% বৃদ্ধি পায়।"
