  Skill_4348_Name = {
    Text = "অনুসন্ধান"
  },
  Skill_4349_AwakerSkillBackgroundStory = {
    Text = "কুচকুচে কালো আঠালো তরল তাকে টেনে নিয়ে গেল অতল গহ্বরে। এখানে নক্ষত্রের জন্ম হয়, এখানে আলো মৃত্যুবরণ করে। এখানে সময় নেই, প্রাণ নেই।\nএকটি কণ্ঠস্বর দূর থেকে এগিয়ে এলো, কালো আলো বিকিরণ করতে করতে।\nসে বলল: তুমি চিরকালের জন্য বদলে যাবে, কারণ তুমি ইতিমধ্যেই পরীদের পথে পা রেখেছ।\nসে এখানে দীর্ঘকাল ভ্রমণ করবে।"
  },
  Skill_4349_Desc_0 = {
    Text = "জেনকিন <Energy:[Energy:Arg1]> পয়েন্ট ম্যানিয়া অর্জন করে। <ExaltIconKeywords:নসিস জাগরণ>: ক্রিটিক্যাল রেট [Arg2]% বৃদ্ধি পায়, জেনকিন প্রতিবার ক্ষতি করলে অস্থায়ী ক্রিটিক্যাল ড্যামেজ +[Arg3]%, প্রতি রাউন্ডে সর্বোচ্চ 5 বার স্ট্যাক করা যায়।"
  },
  Skill_4349_Desc_15 = {
    Text = "জেনকিন <Energy:[Energy:Arg1]> পয়েন্ট উন্মত্ততা অর্জন করে। <ExaltIconKeywords:নসিস জাগরণ>: ক্রিটিক্যাল হার [Arg2]% বৃদ্ধি পায়, জেনকিন প্রতিবার ক্ষতি করলে, অস্থায়ী ক্রিটিক্যাল ক্ষতি +[Arg3]%, প্রতি রাউন্ডে সর্বোচ্চ 5 বার স্ট্যাক করা যায়। জেনকিন নিজে 「স্পেস ফোল্ডিং」 এবং 「ফগ সিটি স্ট্রিট চিলড্রেন」 থেকে 2 গুণ ক্রিটিক্যাল ক্ষতি প্রভাব অর্জন করে।"
  },
