  Skill_4375_AwakerSkillBackgroundStory = {
    Text = "এক পা এক পা করে, সে ধীরে ধীরে সমুদ্রের জলে পা রাখল।\nরাতের সমুদ্র, যা ত্বক স্পর্শ করার মুহূর্তে একটু শীতল মনে হয়েছিল, এই মুহূর্তে মানুষের আলিঙ্গনের মতো উষ্ণ লাগছিল।\nসমুদ্র আমাকে গ্রহণ করেছে — এই ভাবনা নীরবে নিমফিয়ার মনে ভেসে এল।\nহঠাৎ, সে তার বাবা-মায়ের হাসি দেখতে পেল। সমুদ্রের সেই গভীরে, নিশ্চয়ই পরিবারের শান্তি ও সুখ অপেক্ষা করছে।"
  },
  Skill_4375_Desc_0 = {
