  Skill_4381_AwakerSkillBackgroundStory = {
    Text = "রূপান্তরের সময় এসেছে।\nউত্তরাধিকারী সাধারণ মানুষের চেয়ে অনেক বেশি মহান এক সত্তা।\nপরিত্যাগ করো আত্মীয়দের, পরিত্যাগ করো বন্ধুদের, পরিত্যাগ করো যন্ত্রণা, পরিত্যাগ করো অতীতের সবকিছু।\nআমি গৌরবের আশীর্বাদ লাভ করব।\nতার দেহের পৃষ্ঠে ঘন আঁশের কাঁটা গজিয়ে উঠল।"
