  Skill_4384_AwakerSkillBackgroundStory = {
    Text = "যত বেশি সংযম ও দমনের স্থান, মেয়েটির নিয়ন্ত্রণ ক্ষমতা তত বেশি বিস্ময়কর।\nউচ্চ শব্দের চাবুক মিষ্টি প্রেমের ভাষার সমতুল্য, জ্বলন্ত মোমের ফোঁটা উত্তপ্ত চুম্বনের বিকল্প, টানটান দড়ির বন্ধন হলো সূক্ষ্ম যত্নের প্রকাশ, আর ফোলা ক্ষতচিহ্ন হলো ভালোবাসার প্রমাণ।\nসেই মধুবর্ণ বিষাদময় মায়ার মাঝে ভেসে আসে মেয়েটির ঘণ্টাধ্বনির মতো হাসি।"
