  Skill_4388_AwakerSkillBackgroundStory = {
    Text = "অগণিত পুনর্জন্মের চক্রে, সে কারণকে নিজের উপর দৃঢ়ভাবে আরোপ করেছিল, ধাপে ধাপে কার্যকারণের জলাভূমিতে তলিয়ে গেছিল।\nবিরোধাভাস তার দেহকে ছিন্নভিন্ন করেছিল, বিশৃঙ্খলা তার আত্মাকে পূর্ণ করেছিল, আর অন্তহীন যন্ত্রণার মাঝে, সে 'অজানা' থেকে ফুটো হয়ে পড়া এক রশ্মি আলো আঁকড়ে ধরেছিল।"
