  Skill_4442_Name = {
    Text = "প্রহার"
  },
  Skill_4443_AwakerSkillBackgroundStory = {
    Text = "সে একসময় শীর্ষ থেকে নিচে পতিত হয়েছিল, অতীতের গৌরব আজকের অপমানে পরিণত হয়েছে।\nশাসনকর্তার স্ত্রীর প্রাসাদ থেকে বিতাড়িত হওয়ার পর, হেলট অসংখ্য হেলট দাসদের মধ্যে একজন সাধারণ সদস্যে পরিণত হয়, স্পার্টান কারারক্ষীদের নির্যাতনের শিকার হয়। সেই চরম হতাশার মধ্যেও, সে কখনো নিরাশা ও দুর্বলতায় ডুবে যায়নি।\nতার বুকের মধ্যে প্রবলভাবে জ্বলছিল কেবল অন্তহীন ঘৃণা।\nগলার কাঁটাযুক্ত শিকল নির্মমভাবে ছিন্ন হয়েছে, এর মধ্যে বন্দী শক্তি মুক্তি পেয়েছে, প্রকৃত রূপ প্রকাশিত হতে চলেছে।\nআজ থেকে, প্রতিদিন গলা ধুয়ে পরিষ্কার রাখো, আমার প্রতিশোধের জন্য অপেক্ষা করো।"
