  Skill_4492_AwakerSkillBackgroundStory = {
    Text = "সন্ধ্যার বাতাস বয়ে আনবে স্বদেশের ঘণ্টাধ্বনি, তারার আলো আলোকিত করবে ঘরে ফেরার পথ।\nঅতীতের দায়িত্ব তার অন্তরে গেঁথে গেছে এক অদম্য সংকল্প হয়ে।\nসে তার জীবনকে জ্বালানি করে প্রজ্বলিত করতে চায় চিরন্তন প্রদীপ।"
