  Skill_4509_AwakerSkillBackgroundStory = {
    Text = "প্রাচীনতম বিশৃঙ্খলা ছাড়া আর কিছুই সমুদ্রজলকে অগ্নির সঙ্গে মিশিয়ে দিতে পারে না।\nযাচাই করতে চাও তবে যাও খুঁজে দেখো। মরুভূমির সুউচ্চ মিনারগুলোকে তাড়া করো, হারিয়ে যাওয়া জলের নিচের নগরীকে সন্ধান করো, আর আরোহণ করো সীমাহীন পর্বতমালা।\nআমি নিশ্চয়তা দিচ্ছি, লোটানের চেয়ে প্রাচীন আর কিছু নেই।"
