  Skill_4615_AwakerSkillBackgroundStory = {
    Text = "ফেইন্ট অসম্পূর্ণ।\n\nফেইন্ট বিপজ্জনক।\nফেইন্ট অভিশপ্ত।\nফেইন্ট, নক্ষত্রমণ্ডল থেকে আগত, সবচেয়ে রহস্যময় ও বর্ণময় এক রঙের ছটা।"
