  Skill_4644_AwakerSkillBackgroundStory = {
    Text = "বন্দর ছেড়ে যাওয়া জাহাজ বাতাসে পথ হারায়, দল ছেড়ে আসা পশু বিশাল ঢেউ তোলে।\nতার উন্মত্ততা বারবার মানব সভ্যতার অস্তিত্বকে প্রভাবিত করেছে, কিন্তু সে কখনো তার পরোয়া করেনি।\nপশুর কাছে, নিজের আবাসভূমি ফিরে পাওয়ার চেয়ে গুরুত্বপূর্ণ আর কিছু নেই।"
