  Skill_4653_Name = {
    Text = "অস্ত্রোপচার কর্তন"
  },
  Skill_4654_Desc = {
    Text = "[Arg1] চরিত্রের ঢাল অর্জন করো। লিলির আহ্বান করা স্লাইম চরিত্রের ঢাল কেবলমাত্র, এবং শুধুমাত্র, এক নরককুকুরের রেন্ড আঘাত সহ্য করতে পারে। সত্যি... এতে কি একটুও ব্যথা পাবে না?"
  },
  Skill_4654_Name = {
    Text = "কাদার উপর অমর ফুল"
  },
  Skill_4655_AwakerSkillBackgroundStory = {
    Text = "\nসমুদ্র গভীর ও নীরব, বয়ে বেড়ায় জীবনের কামনা আর মৃত্যুভয়ের ভার।\nতবু কেউ কেউ আছে, যারা হাসি আর দুষ্টুমিতে সেই সমুদ্র ভরিয়ে তুলতে চায়—যখন অরিটা এমন আমন্ত্রণ বাড়িয়ে দেয়, তখনই মনে হয়, “ওর সঙ্গে একটু মজা করলেই বা ক্ষতি কী,” আর সহজ সরল আনন্দে হৃদয় ভরে ওঠে।"
  },
  Skill_4655_Desc_0 = {
    Text = "<Damage:[Damage:Arg1]> ক্ষতি করো। ড্র পাইল ও বাতিল তাসের স্তূপ থেকে সর্বোচ্চ ১০টি \"গ্রন্থি বিভাজন\" ব্যয় করো, প্রতিটি অতিরিক্ত ১টি করে ক্ষতির আঘাত যোগ করে। হাতে ২টি \"গ্রন্থি বিভাজন\" নাও। এই যুদ্ধে অরিটার ক্ষতি আউটপুট [Arg2] দ্বারা বৃদ্ধি পায়।"
  },
  Skill_4655_Desc_2 = {
    Text = "<Damage:[Damage:Arg1]> <PunctureDamagewords:ভেদন ক্ষতি> দাও। ড্র পাইল এবং বাতিল তাসের স্তূপ থেকে সর্বোচ্চ 10টি 「গ্রন্থি বিভাজন「 কার্ড ভোগ করো, প্রতিটি অতিরিক্ত একবার করে ক্ষতি ঘটায়। হাতে 2টি 「গ্রন্থি বিভাজন「 কার্ড রাখো। এই যুদ্ধে অরিটা যে ক্ষতি করে, তা [Arg2] পয়েন্ট বৃদ্ধি করো।"
  },
  Skill_4655_EffectNameList = {
    Text = "ক্ষতি,অনুসরণকারী ক্ষতি▲"
  },
  Skill_4655_Name = {
    Text = "কোলাহলময় সমুদ্র"
  },
  Skill_4655_OverLimitUtlSkillDesc_0 = {
    Text = "<Damage:[Damage:Arg1]> পয়েন্ট ক্ষতি করুন। ড্র পাইল ও বাতিল তাসের স্তূপ থেকে সর্বোচ্চ 10টি 「গ্রন্থি বিভাজন」 ব্যয় করুন, প্রতিটির জন্য অতিরিক্ত 1 বার ক্ষতি করুন। 2টি 「গ্রন্থি বিভাজন」 হাতে রাখুন। 「অরিটা」 এই যুদ্ধে পরবর্তীতে যে ক্ষতি করবে তা [Arg2] পয়েন্ট বৃদ্ধি পাবে। [Power:Arg2] পয়েন্ট <PowerIconKeywords:শক্তি> এবং [TentaclePower:Arg2] পয়েন্ট <TentacleInjurieIconKeywords:শুঁড় ক্ষতি> অর্জন করুন, পরবর্তী 5 বার 「গ্রন্থি বিভাজন」 খেলার সময় প্রতিবার 1টি কার্ড ড্র করবে।"
  },
  Skill_4655_OverLimitUtlSkillDesc_2 = {
    Text = "<Damage:[Damage:Arg1]> <PunctureDamagewords:ভেদকারী ক্ষতি> প্রদান করুন। ড্র পাইল এবং বাতিল তাসের স্তূপ থেকে সর্বোচ্চ 10টি 「গ্রন্থি বিভাজন」 কার্ড ভোগ করুন, প্রতিটি অতিরিক্ত 1 বার করে ক্ষতির উদাহরণ যোগ করবে। আপনার হাতে 2টি 「গ্রন্থি বিভাজন」 কার্ড নিন। এই যুদ্ধে অরিটার পরবর্তী ক্ষতি [Arg2] পয়েন্ট বৃদ্ধি পাবে। [Power:Arg2] <PowerIconKeywords:STR> এবং [TentaclePower:Arg2] <TentacleInjurieIconKeywords:শুঁড় ক্ষতি> অর্জন করুন, এবং পরবর্তী 5 বার আপনি 「গ্রন্থি বিভাজন」 খেললে, প্রতি বার 1টি করে কার্ড ড্র করুন।"
  },
