  Skill_4658_AwakerSkillBackgroundStory = {
    Text = "ক্যাসিয়ার দুই হাত শূন্য;\nক্যাসিয়ার টুপি শূন্য;\nক্যাসিয়ার বুক শূন্য।\nশূন্য ক্যাসিয়া শূন্য আনন্দ বহন করে, শূন্য উৎসবে শূন্য পরিবেশনা করে চলে।"
