  Skill_4659_tempBattleDesc_2 = {
    Text = "<Block:[Block:Arg1]> পয়েন্ট শিল্ড অর্জন করুন। <Energy:[Energy:Arg2]> পয়েন্ট উন্মত্ততা অর্জন করুন। এই রাউন্ডে পরবর্তী 1টি 「অদম্য তরবারি」 2 বার কার্যকর হবে।"
