  Skill_4668_AwakerSkillBackgroundStory = {
    Text = "সে মেনে নিতে পারেনি যে সে প্রায় মৃত্যুর কোলে ঢলে পড়েছিল। তার তো অজেয় হওয়ার কথা ছিল, অবিনশ্বর হওয়ার কথা ছিল। যদি মানবদেহ তার শক্তির শীর্ষে পৌঁছানোর পথে বাধা হয়, তবে এই দেহকে পরিত্যাগ করবে; যদি স্বজাতিকে ত্যাগ করলে সে শক্তিশালী হতে পারে, তবে অতীতকে কবর দেবে।\nসে তার বিশাল তরবারি গভীর সমুদ্রে নিক্ষেপ করেছিল, অমানবিক শক্তি ধার করেছিল, এবং শপথ নিয়েছিল সবকিছুর অধিপতি হওয়ার।\nএমনকি যে সত্তা তাকে এই শক্তি দিয়েছে, ভবিষ্যতে তাকেও তার পায়ের তলায় শুয়ে থাকতে হবে।"
