  Skill_4694_AwakerSkillBackgroundStory = {
    Text = "অন্ধকার নিউগেট কারাগারে, লন্ডিনিয়ামে সর্বত্র পাওয়া মোমের তেলও একটি দুর্লভ বস্তু।\nযেহেতু দুর্লভ, তাই এটি গুরুত্বপূর্ণ স্থানে ব্যবহার করতে হবে, যেমন শাস্তির সময়, অবাধ্য শিশুদের ত্বকের উপর।\nবিশেষভাবে তৈরি মোমের তেল নয়, ফোঁটা পড়ার সাথে সাথে করুণ আর্তনাদ ধ্বনিত হয়, কিন্তু সেই কিশোরীর কানে তা যেন মনে হয় সুললিত কবিতার পঙ্ক্তি।"
