  Skill_4701_AwakerSkillBackgroundStory = {
    Text = "সেটি ছিল এক বিকৃত ভ্রূণ, পাপের বীজ।\nসেটি ছিল স্পন্দিত হৃদস্পন্দন, উত্তাল নাড়ির গতি, রক্ত ও অস্থির পরস্পর ঘৃণা, নিয়তির বিপরীত জট।\nসৃষ্ট সত্তার বেছে নেওয়ার স্বাধীনতা নেই, সে কেবল এই বিকৃত গর্ভধারণকে এগিয়ে যেতে দিতে পারে।"
