  Skill_4750_AwakerSkillBackgroundStory = {
    Text = "গর্ভে ধারণ করো, জন্ম দাও, বংশবিস্তার করো।\nক্রমশ গলে যাওয়া বাস্তবতায়, অন্ধকারে ডুবে যাওয়া পৃথিবীতে, নবজন্মের প্রতীক্ষায় থাকা শূন্যতায়।\nতোমাদের অস্তিত্ব মায়ের আত্মত্যাগের ফল, মায়ের ধারাবাহিকতার কারণ।\nহে পবিত্র সন্তানেরা, নতুন পৃথিবীতে পুনর্জন্ম নাও——সেই নিষ্কলুষ, সকল ভয় মুছে যাওয়া নতুন পৃথিবীতে পুনর্জন্ম নাও।"
