  Skill_4758_AwakerSkillBackgroundStory = {
    Text = "সে নতুন নামে পৃথিবীতে পুনর্জন্ম নিল, মুখমণ্ডল আড়াল করে, আর কোনো রূপরেখা নেই।\nপৃথিবীতে যা ছড়িয়ে রইল, তা কেবল তার কণ্ঠে বর্ণিত কবিতাগুলো।\nএটুকুই যথেষ্ট।\nকবির কোনো রূপের প্রয়োজন নেই……তাদের উচিত ঘন কালির আড়ালে, পৃষ্ঠার পেছনে অদৃশ্য হয়ে থাকা।"
