  Skill_4770_AwakerSkillBackgroundStory = {
    Text = "সোরেলের সালোঁতে, বিদায়ের আগে রাউন্ড ড্যান্স একটি ঐতিহ্যবাহী আয়োজন।\nমদ ও আবেগের আমন্ত্রণে, প্রতিবেশী রাজ্যের রাজপুত্র, রাজসভার মন্ত্রী কিংবা ঘনিষ্ঠ পরিচারিকা—সকলেই হাত ধরে নাচের মঞ্চে ঝাঁপিয়ে পড়ে উন্মত্ত উল্লাসে মেতে ওঠে।\nবীণার সুর ক্রমশ ক্ষীণ হয়ে আসে, সালোঁ শেষ হয়, ক্ষমতার দাপট আর দিগন্তরেখা ছুঁয়ে ওঠা ভোরের আলো ছাড়া সোরেলের পাশে আর কিছুই অবশিষ্ট থাকে না।"
  },
