  Skill_4789_AwakerSkillBackgroundStory = {
    Text = "কেউ স্পষ্ট করে বলতে পারে না কেন সেই অশ্রুবিন্দু আকৃতির রূপালি কোর বসানো ছোট্ট ভালুক পুতুলটি, আইজিসি জাগ্রত হওয়ার পর এমন রূপ ধারণ করেছে। এটি হয়তো আইজিসির দেহে থাকা ঊর্ধ্বতন সত্তার শক্তির সাথে সম্পর্কিত, অথবা হয়তো কেবল প্রবল মানসিক শক্তির বিকৃতির ফলে সৃষ্ট রূপান্তর।\n\nযাই হোক না কেন, এটির মধ্যে একটি নির্দিষ্ট মাত্রার আত্ম-সচেতনতা রয়েছে বলে মনে হয়, মাঝে মাঝে আইজিসির অলক্ষ্যে নিজের একটি অংশ বিচ্ছিন্ন করে সুতোর তৈরি আতশবাজির মতো ছড়িয়ে পড়ে।"
