  Skill_4804_AwakerSkillBackgroundStory = {
    Text = "শিখা ছড়িয়ে পড়ে, থিয়েটারের গম্বুজকে পান্নার সবুজে রাঙিয়ে তোলে, যেন ভোরের স্বচ্ছ ও প্রশান্ত হ্রদের জল।\nকতজন এই পান্নাবর্ণ ছায়ার পিছু ছুটে এসেছিল, আর কতজন সেই সাবলীল ও শক্তিময় নৃত্যভঙ্গি উপেক্ষা করে কেবল আবছাভাবে দৃশ্যমান শুভ্র বাহু আর কল্পনায় আঁকা পোশাকের আড়ালের দৃশ্যই দেখেছিল।\nআর নৃত্যশিল্পী কেবল স্থির হয়ে দাঁড়িয়ে ছিলেন সেখানে, সবুজ অগ্নিতে গ্রাসিত মৃত্যুপথযাত্রীর ভঙ্গিমায়।"
