  Skill_4822_AwakerSkillBackgroundStory = {
    Text = "অন্তহীন ভবঘুরে জীবনে, টিঙ্কট তার জন্মভূমির নামটিও ভুলে গেছে।\nদীর্ঘ যুগের পরিক্রমায়, মহাবিশ্বও সেই মৃত গ্রহটির নাম ভুলে গেছে।\nঅগণিত ক্ষয়প্রাপ্ত ও পরিত্যক্ত গ্রহের মতোই, এটিকেও সম্মিলিতভাবে 「জনশূন্য তারা」 বলে ডাকা হয়।\nতার গান, সম্ভবত সেই সীমানার বাইরের গ্রহটির শেষ অনুরণন।"
