  Skill_4864_AwakerSkillBackgroundStory = {
    Text = "দর্শন এমন একটি বিষয় যার কোনো সঠিক উত্তর নেই।\nএটি সভ্যতার সূচনা থেকে প্রবাহিত একটি নদী, যার বিভিন্ন প্রবাহে মানবজাতি ভিন্ন ভিন্ন জলধারা ঢেলে দিয়েছে।\nআর সে নিজের জন্য একটি নতুন খাত খনন করে চলেছে।\nহয়তো, ভবিষ্যতে কোনো একদিন সে নিজের অস্তিত্বের সারসত্তা উপলব্ধি করতে পারবে; হয়তো, সেই দিনটি কখনোই আসবে না।"
  },
  Skill_4864_Desc_0 = {
    Text = "রামোনা <Energy:[Energy:Arg1]> অ্যালিমাস পায়। <ExaltIconKeywords:Rouse>: রামোনা যখনই একটি তাস ব্যবহার করে, সে 1 অ্যারিথমেটিকা অর্জন করে, প্রতি টার্নে সর্বোচ্চ 3 বার পর্যন্ত।"
  },
  Skill_4864_Desc_15 = {
    Text = "রামোনা <Energy:[Energy:Arg1]> আলিয়েমাস পায়। <ExaltIconKeywords:জাগরণ>: রামোনা একটি কার্ড খেললে, সে ১ অ্যারিথমেটিকা পায় এবং রামোনার দ্বারা প্রদত্ত মূল ক্ষতি ১০% বাড়ে, প্রতি টার্নে সর্বোচ্চ ৩ বার পর্যন্ত।"
