  Skill_48812_Desc = {
    Text = "যদি কোনো \"ভ্রূণ\" না থাকে, তবে এটিকে <DevouredIconKeywords:গ্রাস> করা যাবে এবং প্রভাবটি দুইবার সক্রিয় হবে। সরাসরি ব্যবহার করলে বা স্বয়ংক্রিয়ভাবে রূপান্তরিত হলে, এটি \"ভ্রূণ\"-এর প্রভাবের ১.৫ গুণ হিসেবে গণ্য হবে।"
