  Skill_57754_AwakerSkillBackgroundStory = {
    Text = "মৃদু সমুদ্রের বাতাসে সে ঘুমিয়ে পড়েছিল, কিন্তু ডানা ঝাপটানোর শব্দে জেগে উঠল। একটি ধবধবে সাদা পাখি তার মাথার উপর দিয়ে উড়ে গেল, একই রকম শুভ্র মেঘের মাঝে মিলিয়ে গেল।\nনিশ্চয়ই স্বপ্ন ছিল — স্থলভূমি থেকে এত দূরে, মহাসাগরের গভীরে, একটি একাকী পাখি কীভাবে থাকতে পারে?\nসে এই কথা ভাবছিল, তবুও নিজেকে থামাতে পারছিল না — একটি আশার অনুভূতি, একটি আকাঙ্ক্ষা তার মনে জেগে উঠছিল।"
  },
