  Skill_66349_AwakerSkillBackgroundStory = {
    Text = "তিনি অতীত, বর্তমান এবং ভবিষ্যৎ জানেন।\nতিনি জানেন সবকিছু কীভাবে উদ্ভূত হয়, এবং কীভাবে বিলীন হয়।\nতাঁর কানে প্রতিধ্বনিত হয় সেই 'তাঁর' নিঃশ্বাস।"
  },
  Skill_66349_Desc_0 = {
    Text = "হাতে থাকাকালীন, ড্র পাইলের শীর্ষে থাকা কার্ডটি যদি কমান্ড কার্ড হয়, তবে এটি তার একটি অনুলিপিতে রূপান্তরিত হয়। ব্যবহার করার পর মূল রূপে ফিরে আসো এবং <Energy:[Energy:Arg1]> অ্যালিমাস অর্জন করো।"
  },
  Skill_66349_Desc_1 = {
    Text = "হাতে থাকা অবস্থায়, যদি ড্র পাইলের শীর্ষ কার্ডটি একটি কমান্ড কার্ড হয়, তবে এটি তার অনুলিপিতে রূপান্তরিত হয় এবং অ্যারিথমেটিকা ব্যয় 1 কমে যায়। খেলার পর, পূর্বরূপে ফিরে যাও এবং <Energy:[Energy:Arg1]> অ্যালিমাস পাও।"
  },
  Skill_66349_EffectNameList = {
