  Skill_66349_Name = {
    Text = "সর্বজ্ঞ সত্য"
  },
  Skill_66350_AwakerSkillBackgroundStory = {
    Text = "রৌপ্য চাবির দ্বার পেরিয়ে, মানবজাতি তাঁর সিংহাসনের সামনে নতজানু হয়, চূড়ান্ত উত্তরের সন্ধান করে।\nআর সে হলো দ্বাররক্ষী, তার দায়িত্ব নিবৃত্ত করা, স্মরণ করানো, সতর্ক করা।\nনা জানানোই তার করুণা।"
  },
  Skill_66350_BattleDesc_0 = {
    Text = "তাবিল <Energy:[Energy:Arg1]> পয়েন্ট অ্যালিমাস অর্জন করে। হাতে 1 টি「<DerivativeCardKeywords_67:রৌপ্য চাবির ঊষার আলো>」রাখা হয়। তাবিল প্রতি 1 পয়েন্ট অ্যারিথমেটিকা ব্যবহার করলে, 50% রৌপ্য চাবি রিচার্জের S-শক্তি অর্জন করে।"
  },
