  Skill_67855_AwakerSkillBackgroundStory = {
    Text = "এই চোখ দুটি আর স্বাভাবিকভাবে দেখতে পায় না।\nসে সময় ও বাস্তবতার ঝড়ের মুখোমুখি দাঁড়িয়েছিল, গর্জনকারী বিশৃঙ্খলাকে নিজেকে ছিন্নভিন্ন করতে, চূর্ণবিচূর্ণ করতে দিয়েছিল, এবং অবশেষে তা তার চোখে পরিণত হয়েছে।\n'রামোনা'-র আরেকটি চিহ্ন তার শরীর থেকে মুছে যাচ্ছে। সে হারিয়ে যাওয়া নিজেকে ধরে রাখতে পারছে না, ঠিক যেমন সে আঙুলের ফাঁক দিয়ে পিছলে যাওয়া জীবনকে ধরে রাখতে পারেনি।"
  },
