  Skill_95810_UnknownName = {
    Text = "নিষ্ঠুর অভিবাদন"
  },
  Skill_95811_AwakerSkillBackgroundStory = {
    Text = "আমন্ত্রণপত্রের কাগজ তৈরি হয়েছে কোমল ত্বক থেকে। আমন্ত্রণপত্রের অলংকরণ এসেছে মসৃণ করোটি থেকে। আমন্ত্রণপত্রের লেখা লেখা হয়েছে তাজা রক্ত দিয়ে। আমন্ত্রণপত্রের স্বাক্ষর এসেছে রাজপ্রাসাদের সেই উষ্ণ আতিথেয়তার মালিকের কাছ থেকে।\nদুলেসাইন আপনাকে আন্তরিক আমন্ত্রণ জানাচ্ছেন, আপনাদের জন্য আয়োজিত এই মহাভোজে যোগ দিতে।"
  },
  Skill_95811_Desc_0 = {
    Text = "দুলেসাইন <Energy:[Energy:Arg1]> পয়েন্ট অ্যালিমাস অর্জন করুন। <ExaltIconKeywords:জাগরণ>：[Power:Arg2] পয়েন্ট <PowerIconKeywords:শক্তি> অর্জন করুন, দুলেসাইনের দেওয়া ক্ষতি অতিরিক্ত [Arg3]％ শক্তি বোনাস উপভোগ করে। দুলেসাইন প্রতি রাউন্ডে প্রথমবার হত্যা করার পর, অন্যান্য শত্রুদের উপর ৫০% উপচে পড়া ক্ষতির <FixedDamage:বিশুদ্ধ ক্ষতি> প্রয়োগ করুন।"
  },
  Skill_95811_Desc_15 = {
    Text = "দুলেসাইন <Energy:[Energy:Arg1]> পয়েন্ট অ্যালিমাস অর্জন করে। <ExaltIconKeywords:জাগরণ>：[Power:Arg2] পয়েন্ট <PowerIconKeywords:শক্তি> অর্জন করে, দুলেসাইনের দেওয়া ক্ষতি অতিরিক্তভাবে [Arg3]％ শক্তি বোনাস উপভোগ করে। সমস্ত শত্রুর বর্তমান জীবনের [Arg4]％ <FixedDamage:বিশুদ্ধ ক্ষতি> করে। দুলেসাইন প্রতি রাউন্ডে প্রথমবার হত্যা করার পর, অন্য শত্রুদের উপর 100% উপচে পড়া ক্ষতির <FixedDamage:বিশুদ্ধ ক্ষতি> করে।"
